--    AI-1 pipeline ใช้อ้างอิง การลบทั้งชุดแล้วเขียนใหม่เสี่ยงเกินความจำเป็น)
-- 🔴 lucky_number: เก็บลงฐานเพื่อความครบถ้วนของข้อมูลต้นทาง **แต่ระบบไม่แสดงให้ผู้ใช้เห็น**
--    (เป็นภาษาใบ้หวยตรงๆ ขัดกับ guardrail ที่ปฏิเสธคำถามหวยอยู่แล้ว — รอผู้ใช้ตัดสินก่อนเปิดใช้)

ALTER TABLE dream_symbols ADD COLUMN IF NOT EXISTS shape_meaning TEXT;
ALTER TABLE dream_symbols ADD COLUMN IF NOT EXISTS lucky_number TEXT;

-- 1) เพิ่มหมวดสัตว์บก 30 รายการ (ข้ามถ้ามีอยู่แล้ว — รันซ้ำได้)
INSERT INTO dream_symbols (category, dream_object, chinese_char, kangxi_strokes, element, meaning_keyword, shape_meaning, lucky_number, source)
SELECT v.category, v.dream_object, v.chinese_char, v.kangxi_strokes, v.element, v.meaning_keyword, v.shape_meaning, v.lucky_number, 'kangxi_v3'
FROM (VALUES
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม (Land Mammals)', 'สุนัข / หมา', '狗', 8::INT, 'ดิน', 'ความซื่อสัตย์, มิตรแท้/บริวารที่ไว้ใจได้, ข่าวสารจากคนใกล้ตัว, การเฝ้าระวังภัย (เห่า=มีคนเตือน)', 'สี่ขามั่นคง = ฐานะที่มั่นคง; หางกระดิก = ข่าวดี/การต้อนรับ; ถ้ากัด = ปากเสียงกับคนใกล้ชิด', 'เด่น 08-80 · วิ่ง 0 8'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'แมว', '貓', 16::INT, 'ไม้', 'ผู้หญิงเจ้าเสน่ห์/ลึกลับ, โชคที่มาเงียบๆ, สัญชาตญาณเตือนภัย, ความอิสระเอาแต่ใจ', 'ตาที่เรืองในความมืด = การมองเห็นสิ่งที่ผู้อื่นไม่เห็น; ตัวอ่อนพลิ้ว = การปรับตัวรอดในทุกสถานการณ์', 'เด่น 16-61 · วิ่ง 1 6 7'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'วัว / โค', '牛', 4::INT, 'ดิน', 'ความขยันอดทน, ทรัพย์สินไร่นา, งานหนักที่ให้ผล, ความมั่งคั่งแบบค่อยเป็นค่อยไป', 'ลำตัวใหญ่แข็งแรง = กำลังทรัพย์/แรงงานสะสม; เขาโค้ง = การป้องกันผลประโยชน์ของตน', 'เด่น 04-40 · วิ่ง 0 4'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'ควาย / กระบือ', '兕', 7::INT, 'ดิน', 'แรงงานหนักเพื่อครอบครัว, ความอดทนต่อความลำบาก, คนซื่อถูกใช้งาน, ที่ดินเรือกสวน', 'ตัวใหญ่ลุยโคลน = ฝ่าอุปสรรคที่หนักหน่วง; เขาคู่กว้าง = พลังต้านทานและความดื้อรั้น', 'เด่น 07-70 · วิ่ง 0 7'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'หมู', '豬', 15::INT, 'น้ำ', 'โชคลาภกินดีอยู่ดี, ความอุดมสมบูรณ์, เงินทองไหลมา (แต่ใช้จ่ายง่าย), ความสบายเกียจคร้าน', 'ตัวอวบอ้วน = ความบริบูรณ์พูนสุข; นอนนิ่ง = ทรัพย์ที่งอกเงยโดยไม่ต้องดิ้นรน', 'เด่น 15-51 · วิ่ง 1 5 6'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'หมูป่า', '豕', 7::INT, 'น้ำ', 'พลังดิบ, ศัตรูที่บุกตะลุย, โชคจากการเสี่ยง, ความมุทะลุที่ต้องระวัง', 'งาแหลมพุ่งชน = อุปสรรคที่ปะทะตรงๆ; ตัวกำยำในป่า = ทรัพย์ที่ต้องออกไปไขว่คว้าเอง', 'เด่น 07-70 · วิ่ง 0 7'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'ม้า', '馬', 10::INT, 'ไฟ', 'ความก้าวหน้ารวดเร็ว, การเดินทาง/ย้ายที่, ข่าวไกล, ชัยชนะและชื่อเสียง', 'ขายาวพุ่งทะยาน = ความสำเร็จที่มาไว; แผงคอสง่า = เกียรติยศและการเป็นที่จับตา', 'เด่น 10-01 · วิ่ง 1 0'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'ลา', '驢', 26::INT, 'ดิน', 'งานหนักปิดทองหลังพระ, ความอดทนถึกทน, ภาระที่แบกไว้, ผลตอบแทนช้าแต่แน่นอน', 'แบกของบนหลัง = ภาระหน้าที่ที่ต้องรับ; ตัวเล็กแต่ทน = อึดสู้งานที่คนอื่นทำไม่ไหว', 'เด่น 26-62 · วิ่ง 2 6 8'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'อูฐ', '駝', 15::INT, 'ดิน', 'ความอดทนข้ามวิกฤต, การสะสมเสบียง/ทุนสำรอง, การเดินทางไกลลำบากแต่ถึงเป้า, ความมั่งคั่งจากการอดออม', 'โหนกเก็บพลัง = เงินสำรองไว้ยามยาก; เดินฝ่าทะเลทราย = ผ่านช่วงแล้งไปสู่ความสำเร็จ', 'เด่น 15-51 · วิ่ง 1 5 6'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'แพะ', '羊', 6::INT, 'ดิน', 'ความอ่อนโยนมีเมตตา, โชคลาภและความเจริญ (羊=祥 มงคล), สันติสุขในบ้าน, การรวมกลุ่ม', 'เขาโค้งม้วน = ทรัพย์ที่ม้วนกลับคืน; ขนปุยนุ่ม = ความมั่งคั่งที่อบอุ่นสบายใจ', 'เด่น 06-60 · วิ่ง 0 6'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'แกะ / ลูกแกะ', '羔', 10::INT, 'ดิน', 'ความบริสุทธิ์อ่อนต่อโลก, โชคของผู้เริ่มต้น, การได้รับการดูแล, ความเปราะบางที่ต้องปกป้อง', 'ตัวเล็กขนขาว = การเริ่มต้นที่สะอาดใหม่; ยืนเคียงฝูง = ความปลอดภัยเมื่ออยู่กับพวกพ้อง', 'เด่น 10-01 · วิ่ง 1 0'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'เสือ', '虎', 8::INT, 'ไม้', 'อำนาจบารมี, ผู้ใหญ่มีอิทธิพล, ความกล้าเผชิญ, ศัตรูที่น่าเกรงขาม (ขี่เสือ=จำใจสู้ต่อ)', 'ลายพาดกลอน = อำนาจที่โดดเด่นสะดุดตา; เขี้ยวเล็บคม = แสนยานุภาพและการข่มขู่คู่แข่ง', 'เด่น 08-80 · วิ่ง 0 8'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'เสือดาว', '豹', 10::INT, 'ทอง', 'ความเร็วฉับไว, การจู่โจมคว้าโอกาส, ความสามารถซ่อนเร้น, ศัตรูที่ปราดเปรียว', 'ลายจุดพรางตัว = ความสามารถที่ซ่อนไว้รอจังหวะ; ตัวเพรียวลม = การฉวยโอกาสอย่างแม่นยำ', 'เด่น 10-01 · วิ่ง 1 0'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'สิงโต', '獅', 13::INT, 'ทอง', 'อำนาจสูงสุด, เกียรติยศ, ผู้นำที่คนยำเกรง, การปกป้องคุ้มครอง (สิงโตหิน=กันภัย)', 'แผงคอสง่างาม = บารมีและรัศมีผู้นำ; ท่วงท่าองอาจ = ความมั่นใจที่ทำให้ผู้อื่นสยบ', 'เด่น 13-31 · วิ่ง 1 3 4'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'ช้าง', '象', 11::INT, 'ดิน', 'อำนาจวาสนายิ่งใหญ่, ทรัพย์สมบัติมั่นคง, ผู้ใหญ่อุปถัมภ์, ความสำเร็จที่ยั่งยืน (ช้างเผือก=ลาภยศชั้นสูง)', 'กายมหึมา = ฐานะและบารมีอันใหญ่โต; งวงคว้ายกของ = ความสามารถกอบโกยทรัพย์; งายาว=ยศศักดิ์', 'เด่น 11 · วิ่ง 1 2'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'ลิง', '猴', 12::INT, 'ทอง', 'ความเฉลียวฉลาดพลิกแพลง, ยศศักดิ์ (猴=侯 ขุนนาง), การค้าที่คล่องแคล่ว, ความซุกซนวุ่นวายเรื่องเล็ก', 'มือไวปีนป่าย = ความคล่องแคล่วไขว่คว้าโอกาส; หน้าตาแสนรู้ = ไหวพริบเอาตัวรอด', 'เด่น 12-21 · วิ่ง 1 2 3'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'ชะนี / วานร', '猿', 13::INT, 'ทอง', 'ความผูกพันโหยหา (เสียงชะนี=คิดถึงคนไกล), ความสันโดษ, สติปัญญาชั้นสูง, ข่าวจากแดนไกล', 'แขนยาวโหนกิ่ง = การเอื้อมไปถึงสิ่งที่อยู่ไกล; อยู่ยอดไม้สูง = มุมมองที่เหนือกว่าผู้อื่น', 'เด่น 13-31 · วิ่ง 1 3 4'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'หนู', '鼠', 13::INT, 'น้ำ', 'ความมั่งคั่งที่สะสมทีละน้อย, ไหวพริบเอาตัวรอด, โชคลาภเล็กๆ ต่อเนื่อง, ระวังของหาย/คนแอบฉวย', 'ตัวเล็กมุดรู = ช่องทางทำกินที่คนมองข้าม; ฟันแทะเก็บสะสม = การเก็บออมทีละนิดจนมั่งมี', 'เด่น 13-31 · วิ่ง 1 3 4'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'กระต่าย', '兔', 8::INT, 'ไม้', 'ความว่องไวปราดเปรียว, โชคด้านความรัก/บุตร, ความอ่อนหวานเป็นที่รัก, การหลบหลีกภัยได้ทัน', 'ขาหลังทรงพลัง = การกระโจนหนีอันตรายได้ไว; หูยาวไว = การรับข่าวสารก่อนใคร', 'เด่น 08-80 · วิ่ง 0 8'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'กวาง', '鹿', 11::INT, 'ไม้', 'ยศถาบรรดาศักดิ์และเงินเดือน (鹿=祿 ลาภยศ), ความสง่างามอ่อนโยน, โชคลาภในป่าเขา, คู่ครองที่ดี', 'เขากิ่งก้านแตกแขนง = ตำแหน่งลาภที่งอกงามหลายทาง; ลำตัวสง่า = เกียรติที่มาพร้อมความนุ่มนวล', 'เด่น 11 · วิ่ง 1 2'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'หมี', '熊', 14::INT, 'ดิน', 'พละกำลังมหาศาล, ความมั่นคงหนักแน่น, ผู้ปกป้องที่ทรงพลัง, อุปสรรคใหญ่ที่ต้องใช้แรงฝ่า', 'อุ้งเท้าหนา = พลังทุบทำลายสิ่งกีดขวาง; ตัวใหญ่จำศีล = การสะสมกำลังรอวันลุก', 'เด่น 14-41 · วิ่ง 1 4 5'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'หมาป่า', '狼', 10::INT, 'ทอง', 'ความทะเยอทะยานดุดัน, การทำงานเป็นทีม (ฝูงหมาป่า), ความโลภที่ต้องระวัง, ศัตรูที่รวมหัวกัน', 'เขี้ยวคมล่าเป็นฝูง = พลังหมู่คณะที่น่ากลัว; ตาจับจ้องเหยื่อ = ความมุ่งมั่นไม่ปล่อยเป้าหมาย', 'เด่น 10-01 · วิ่ง 1 0'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'จิ้งจอก', '狐', 8::INT, 'ไม้', 'เล่ห์เหลี่ยมไหวพริบ, เสน่ห์มายา, คนเจ้าเล่ห์รอบตัว, โอกาสจากการใช้ปัญญา (แต่ระวังถูกหลอก)', 'หางฟูใหญ่ = เสน่ห์และภาพลักษณ์ที่ดึงดูด; ย่างก้าวเงียบ = แผนการที่ซ่อนเร้นแนบเนียน', 'เด่น 08-80 · วิ่ง 0 8'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'แรด', '犀', 12::INT, 'ดิน', 'พลังบุกทะลวง, เกราะป้องกันภัย, ความดื้อดึงไม่ยอมแพ้, ทรัพย์หายากมีค่า (นอแรด=ของทรงคุณค่า)', 'หนังหนาเป็นเกราะ = ภูมิคุ้มกันต่อคำนินทา/ศัตรู; นอแหลมตรง = การพุ่งชนอุปสรรคตรงจุด', 'เด่น 12-21 · วิ่ง 1 2 3'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'เม่น', '猬', 12::INT, 'ทอง', 'การป้องกันตัวเมื่อถูกคุกคาม, การตั้งรับที่แหลมคม, เก็บตัวสงวนท่าที, ศัตรูที่แตะต้องยาก', 'ขนแหลมตั้งชัน = การพร้อมสวนกลับทันทีที่ถูกรุกล้ำ; ขดตัวกลม = การปิดตัวป้องกันจุดอ่อน', 'เด่น 12-21 · วิ่ง 1 2 3'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'กระรอก', '鼯', 20::INT, 'ไม้', 'ความคล่องแคล่วเก็บออม, การสะสมเสบียงเผื่ออนาคต, โชคเล็กๆ จากความขยัน, ความร่าเริงว่องไว', 'กระโดดข้ามกิ่ง = ความคล่องตัวคว้าโอกาสหลายทาง; ตุนอาหารในโพรง = การวางแผนสำรองไว้ล่วงหน้า', 'เด่น 20-02 · วิ่ง 2 0'),
  ('สัตว์บก / สัตว์เลี้ยงลูกด้วยนม', 'พังพอน', '鼬', 18::INT, 'ไม้', 'ผู้กล้าสู้ศัตรูที่ใหญ่กว่า (พังพอนสู้งู), ไหวพริบปราดเปรียว, การพลิกสถานการณ์, ระวังคนหน้าไหว้หลังหลอก', 'ตัวเรียวปราดเปรียว = การลอดหลบและจู่โจมที่รวดเร็ว; กล้าปะทะงูพิษ = ใจกล้าท้าชนผู้มีอำนาจ', 'เด่น 18-81 · วิ่ง 1 8 9'),
